//! 🧪️ Closed caller transport laws preserve finite credit, cancellation and original native causes.
use super::*;
use std::sync::{Arc,Mutex};
#[semio_framework_async_macros::async_test]
async fn command_transport_neutral_owner_cancellation_progress_and_source(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let maximum=fixture["maximumTransportBytes"].as_u64().unwrap();
 let token=CancelToken::root_now();let events=Arc::new(Mutex::new(Vec::new()));let received=events.clone();let context=admit_command_transport(maximum,token.clone(),move|event|received.lock().unwrap().push(event)).unwrap();
 assert!(context.allocated_bytes()>0);assert!(context.allocated_bytes()<maximum as usize);let context=CommandContext::try_new(context,maximum,token.clone(),|_|{}).unwrap();
 let directory=std::path::PathBuf::from(std::env::var_os("SEMIO_TEST_ARTIFACT_DIR").expect("caller-authored test artifact directory")).join("command-transport-neutral");std::fs::create_dir_all(&directory).unwrap();let path=directory.join("input");let payload=fixture["payload"].as_str().unwrap().as_bytes();std::fs::write(&path,payload).unwrap();
 assert_eq!(&*read_command_file(&path,maximum,&context).await.unwrap(),std::fs::read(&path).unwrap().as_slice());assert!(events.lock().unwrap().iter().any(|event|event.phase==crate::os_pack::PackTransportPhase::AfterOperation&&event.bytes==payload.len()));
 let missing=directory.join("missing");let error=read_command_file(&missing,maximum,&context).await.unwrap_err();let PackError::TransportFailure(source)=error else{panic!("actual native source")};assert!(std::error::Error::source(&source).unwrap().downcast_ref::<std::io::Error>().is_some());drop(source);
 token.cancel_now();let canceled=read_command_file(&path,maximum,&context).await.unwrap_err();let PackError::Refusal(refusal)=canceled else{panic!("actual caller cancellation")};assert_eq!(refusal.kind(),ValueRefusalKind::Canceled);
 let error=admit_command_transport(0,CancelToken::root_now(),|_|{}).err().expect("finite cell refusal");let PackError::Refusal(refusal)=error else{panic!("actual finite refusal")};assert_eq!(refusal.kind(),ValueRefusalKind::OwnershipLimit);
 let token=CancelToken::root_now();let midway=token.clone();let completed=std::sync::atomic::AtomicUsize::new(0);let context=admit_command_transport(maximum,token.clone(),move|event|{if event.phase==crate::os_pack::PackTransportPhase::AfterOperation&&completed.fetch_add(event.bytes,std::sync::atomic::Ordering::SeqCst)+event.bytes>=65536{midway.cancel_now()}}).unwrap();let context=CommandContext::try_new(context,maximum,token,|_|{}).unwrap();std::fs::write(&path,vec![b'x';131072]).unwrap();let error=read_command_file(&path,maximum,&context).await.err().expect("actual page cancellation");let PackError::Refusal(refusal)=error else{panic!("actual page cancellation")};assert_eq!(refusal.kind(),ValueRefusalKind::Canceled);
 std::fs::write(&path,payload).unwrap();let token=CancelToken::root_now();let transport=admit_command_transport(maximum,token.clone(),|_|{}).unwrap();let memory=Arc::new(Mutex::new(Vec::new()));let recorded=memory.clone();let context=CommandContext::try_new(transport,(payload.len()*2)as u64,token,move|event|recorded.lock().unwrap().push(event)).unwrap();
 let first=read_command_file(&path,maximum,&context).await.unwrap();let second=read_command_file(&path,maximum,&context).await.unwrap();assert_eq!(memory.lock().unwrap().last().unwrap().live_bytes,payload.len()*2);let error=read_command_file(&path,maximum,&context).await.unwrap_err();let PackError::Refusal(refusal)=error else{panic!("finite retained input refusal")};assert_eq!(refusal.kind(),ValueRefusalKind::OwnershipLimit);drop(first);assert_eq!(memory.lock().unwrap().last().unwrap().live_bytes,payload.len());drop(second);assert_eq!(memory.lock().unwrap().last().unwrap().live_bytes,0);assert_eq!(memory.lock().unwrap().last().unwrap().cumulative_bytes,payload.len()*2);assert!(read_command_file(&path,maximum,&context).await.is_err());
 let token=CancelToken::root_now();let transport=admit_command_transport(maximum,token.clone(),|_|{}).unwrap();let context=CommandContext::try_new(transport,maximum,token,|_|panic!("original input observer panic")).unwrap();let error=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||semio_framework_async::block_on(read_command_file(&path,maximum,&context)))).unwrap_err();assert_eq!(error.downcast_ref::<&'static str>(),Some(&"original input observer panic"));assert_eq!(context.inputs.state.lock().unwrap().live,0);
 println!("[DEBUG] native caller cancellation and original stdIo source retained; two actual input Vec owners remain charged until Drop, cumulative credit is not reset and original observer panic settles live credit");
}

#[semio_framework_async_macros::async_test]
async fn command_transport_neutral_utf8_transfer_cancellation_and_exact_owner(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let recipe=&fixture["textTransfer"];let maximum=fixture["maximumTransportBytes"].as_u64().unwrap();let payload=recipe["prefix"].as_str().unwrap().repeat(recipe["prefixRepeat"].as_u64().unwrap()as usize)+recipe["tail"].as_str().unwrap();
 let directory=std::path::PathBuf::from(std::env::var_os("SEMIO_TEST_ARTIFACT_DIR").unwrap()).join("command-text-transfer");std::fs::create_dir_all(&directory).unwrap();let path=directory.join("input");std::fs::write(&path,payload.as_bytes()).unwrap();
 let token=CancelToken::root_now();let transport=admit_command_transport(maximum,token.clone(),|_|{}).unwrap();let context=CommandContext::try_new(transport,maximum,token.clone(),|_|{}).unwrap();let bytes=read_command_file(&path,maximum,&context).await.unwrap();let capacity=bytes.bytes.capacity();let text=bytes.into_text().unwrap();assert_eq!(&*text,payload);assert_eq!(text.text.capacity(),capacity);assert_eq!(context.inputs.state.lock().unwrap().live,payload.len());drop(text);assert_eq!(context.inputs.state.lock().unwrap().live,0);
 let token=CancelToken::root_now();let transport=admit_command_transport(maximum,token.clone(),|_|{}).unwrap();let context=CommandContext::try_new(transport,maximum,token.clone(),|_|{}).unwrap();let bytes=read_command_file(&path,maximum,&context).await.unwrap();token.cancel_now();let error=bytes.into_text().err().expect("actual cancellation before UTF8 validation");let PackError::Refusal(refusal)=error else{panic!("typed UTF8 cancellation")};assert_eq!(refusal.kind(),ValueRefusalKind::Canceled);assert_eq!(context.inputs.state.lock().unwrap().live,0);
 let token=CancelToken::root_now();let transport=admit_command_transport(maximum,token.clone(),|_|{}).unwrap();let armed=Arc::new(std::sync::atomic::AtomicBool::new(false));let observe=armed.clone();let cancel=token.clone();let context=CommandContext::try_new(transport,maximum,token,move|event|{if observe.load(std::sync::atomic::Ordering::SeqCst)&&event.requested_bytes==0&&event.live_bytes>0{cancel.cancel_now()}}).unwrap();let bytes=read_command_file(&path,maximum,&context).await.unwrap();armed.store(true,std::sync::atomic::Ordering::SeqCst);let error=bytes.into_text().err().expect("actual interior UTF8 page cancellation");let PackError::Refusal(refusal)=error else{panic!("typed UTF8 interior cancellation")};assert_eq!(refusal.kind(),ValueRefusalKind::Canceled);assert_eq!(context.inputs.state.lock().unwrap().live,0);
 let token=CancelToken::root_now();let transport=admit_command_transport(maximum,token.clone(),|_|{}).unwrap();let context=CommandContext::try_new(transport,maximum,token,|_|{}).unwrap();let invalid:Vec<u8>=recipe["invalid"].as_array().unwrap().iter().map(|byte|byte.as_u64().unwrap()as u8).collect();assert!(std::str::from_utf8(&invalid).is_err());std::fs::write(&path,&invalid).unwrap();let error=read_command_file(&path,maximum,&context).await.unwrap().into_text().err().expect("original invalid UTF8");let PackError::Refusal(refusal)=error else{panic!("typed UTF8 input")};assert_eq!(refusal.kind(),ValueRefusalKind::InvalidValue);assert_eq!(context.inputs.state.lock().unwrap().live,0);
 println!("[DEBUG] actual UTF8 transfer retains exact backing across a split multibyte scalar, cancellation before/interior and malformed input retire its paid owner");
}
